u64 get_nested_nlattr(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    struct sk_buff *skb = (struct sk_buff *)(long)ctx;
    struct nlattr *nla = (struct nlattr *)(skb->data + A);

    if (skb_is_nonlinear(skb) || skb->len < A + sizeof(*nla))
        return 0;

    if (nla->nla_len < sizeof(*nla) || nla->nla_len > skb->len - A)
        return 0;

    nla = (struct nlattr *)((void *)nla + sizeof(*nla));
    while ((void *)nla < skb->data + skb->len - sizeof(*nla)) {
        if (nla->nla_type == X)
            return (u64)((void *)nla - skb->data);
        if (nla->nla_len < sizeof(*nla) || nla->nla_len > skb->len - (void *)nla + skb->data)
            break;
        nla = (struct nlattr *)((void *)nla + nla->nla_len);
    }
    return 0;
}

u64 retrieve_nested_netlink_attr(u64 ctx, u64 A, u64 X, u64 r4, u64 r5) {
    struct sk_buff *skb = (struct sk_buff *)(long)ctx;
    struct nlattr *nla;
    int len;
    u64 start, end;

    if (!skb)
        return 0;

    if (skb_is_nonlinear(skb))
        return 0;

    if (skb->len < A + NLATTR_HDRLEN)
        return 0;

    start = A;
    end = skb->len;

    nla = (struct nlattr *)((char *)skb->data + start);
    len = nla->nla_len;

    if (start + len > end)
        return 0;

    nla = (struct nlattr *)((char *)skb->data + start);
    nla = nla_next(nla, &len);

    while (nla) {
        if (nla->nla_type == X)
            return (u64)((char *)nla - skb->data);

        nla = nla_next(nla, &len);
    }

    return 0;
}

